"use client";

import { useCart } from "@/context/CartContext";
import { useBooks } from "@/context/BookContext";
import { Trash2 } from "lucide-react";
import { useState } from "react";
import { useLoans } from "@/context/LoanContext";


export default function CartPage() {

  const {
    cart,
    removeFromCart,
    clearCart,
  } = useCart();


  const {
    borrowBook,
  } = useBooks();

  const {
 addLoan
}=useLoans();


  const [message,setMessage] =
    useState("");



  function confirmLoan(){

    let success = true;


cart.forEach((book)=>{

 const borrowed =
 borrowBook(book.id);


 if(borrowed){

   addLoan(book);

 }
 else{

   success=false;

 }

});



    if(success){

      clearCart();

      setMessage(
        "✅ Loan confirmed successfully!"
      );

    }
    else{

      setMessage(
        "❌ Some books are no longer available"
      );

    }



    setTimeout(()=>{

      setMessage("");

    },3000);

  }



  return (

    <main className="min-h-screen bg-gray-100 p-8">



      <h1 className="mb-8 text-4xl font-bold">
        📚 Borrow List
      </h1>



      {cart.length === 0 && (

        <div className="rounded-xl bg-white p-10 text-center shadow">

          <h2 className="text-2xl font-bold">
            Your borrow list is empty
          </h2>


          <p className="mt-3 text-gray-500">
            Choose a book to start your loan.
          </p>


        </div>

      )}



      <div className="grid gap-5">


        {cart.map((book)=>(


          <div
            key={book.id}
            className="
            flex
            items-center
            gap-5
            rounded-xl
            bg-white
            p-5
            shadow
            transition
            hover:-translate-y-1
            hover:shadow-xl
            "
          >


            <img
              src={book.image}
              alt={book.title}
              className="
              h-28
              w-20
              rounded-lg
              object-cover
              "
            />



            <div className="flex-1">


              <h2 className="text-xl font-bold">
                {book.title}
              </h2>



              <p className="text-gray-600">
                {book.author}
              </p>



              <span
                className="
                mt-2
                inline-block
                rounded-full
                bg-blue-100
                px-3
                py-1
                text-sm
                text-blue-700
                "
              >
                1 copy
              </span>



            </div>




            <button

              onClick={() =>
                removeFromCart(book.id)
              }

              className="
              flex
              items-center
              gap-2
              rounded-lg
              bg-red-600
              px-4
              py-2
              text-white
              transition
              hover:bg-red-700
              active:scale-95
              "

            >

              <Trash2 size={18}/>

              Remove


            </button>



          </div>


        ))}


      </div>





      {cart.length > 0 && (


        <div
          className="
          mt-8
          flex
          justify-between
          rounded-xl
          bg-white
          p-6
          shadow
          "
        >


          <button

            onClick={clearCart}

            className="
            rounded-lg
            border
            px-6
            py-3
            transition
            hover:bg-gray-100
            "

          >

            Clear List

          </button>





          <button

            onClick={confirmLoan}

            className="
            rounded-xl
            bg-green-600
            px-10
            py-3
            text-white
            transition
            hover:bg-green-700
            active:scale-95
            "

          >

            Confirm Loan


          </button>



        </div>


      )}






      {message && (

        <div
          className="
          fixed
          bottom-8
          right-8
          rounded-xl
          bg-black
          px-6
          py-4
          text-white
          shadow-2xl
          animate-bounce
          "
        >

          {message}

        </div>

      )}



    </main>

  );

}